<script setup lang="ts">
import { ref, nextTick, watch } from 'vue'; import { MessageCircle, X, Send, Sparkles } from 'lucide-vue-next'; import { http, errorMessage } from '../api/http'; import type { Product } from '../types'
const open = ref(false), input = ref(''), busy = ref(false), error = ref(''), messages = ref<{ role: string; text: string; products?: Product[] }[]>([]), area = ref<HTMLElement>(), panel = ref<HTMLElement>(), launcher = ref<HTMLButtonElement>(); watch(open, async v => { await nextTick(); if (v) panel.value?.querySelector<HTMLInputElement>('input')?.focus(); else launcher.value?.focus() }); async function send(text = input.value) { if (busy.value || text.trim().length < 2) return; input.value = ''; error.value = ''; messages.value.push({ role: 'user', text }); if (messages.value.length > 12) messages.value.splice(0, 2); busy.value = true; try { const { data } = await http.post('/chat', { message: text }); messages.value.push({ role: 'assistant', text: data.answer, products: data.products }) } catch (e) { error.value = errorMessage(e) } finally { busy.value = false; await nextTick(); area.value?.scrollTo({ top: area.value.scrollHeight, behavior: 'smooth' }) } }
</script>
<template><section v-if="open" id="booknest-chat" ref="panel" class="chat-panel" role="region" aria-label="Trợ lý tư vấn sách" @keydown.esc.stop="open = false"><header><div><Sparkles :size="19" /><strong>Trợ lý BookNest</strong></div><button class="icon-btn" aria-label="Đóng chat" @click="open = false"><X :size="19" /></button></header><div ref="area" class="chat-messages" role="log" aria-live="polite" aria-relevant="additions"><p class="chat-intro">Xin chào! Bạn muốn khám phá cuốn sách nào hôm nay?</p><template v-if="!messages.length"><button class="suggestion" @click="send('Gợi ý sách kỹ năng sống dưới 150.000 đồng')">Sách kỹ năng sống dưới 150.000đ</button><button class="suggestion" @click="send('Tôi mới học lập trình, nên đọc sách nào?')">Sách cho người mới học lập trình</button></template><div v-for="(m, i) in messages" :key="i" class="chat-message" :class="m.role"><p>{{ m.text }}</p><RouterLink v-for="p in m.products" :key="p.id" :to="`/products/${p.id}`" @click="open = false">{{ p.name }} →</RouterLink></div><p v-if="busy" class="chat-busy" role="status">Đang tìm sách phù hợp…</p><p v-if="error" class="alert error" role="alert">{{ error }}</p></div><form @submit.prevent="send()"><label class="sr-only" for="chat-input">Câu hỏi tư vấn</label><input id="chat-input" v-model="input" maxlength="1000" placeholder="Bạn đang tìm sách gì?" required minlength="2"><button class="icon-btn" :disabled="busy || input.trim().length < 2" aria-label="Gửi câu hỏi"><Send :size="20" /></button></form><small>AI có thể sai. Vui lòng kiểm tra thông tin sản phẩm.</small></section><button ref="launcher" class="chat-launch" aria-controls="booknest-chat" :aria-expanded="open" aria-label="Tư vấn chọn sách" @click="open = !open"><X v-if="open" :size="23" /><MessageCircle v-else :size="23" /><span v-if="!open">Tư vấn sách</span></button></template>